import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'

import { cn } from '@/lib/cn'

/**
 * Toasts: bottom-right, dark ink fill, 8px stack gap.
 *
 * Confirmations in this app name their consequence -- not "Saved" but
 * "Entry posted." `message` is therefore a sentence, not a status word.
 *
 * The tone is carried by a single leading glyph (green ✓ / amber ● / red ●),
 * never by a coloured background: a large green fill behind text is explicitly
 * out of bounds in this system.
 *
 * **An error toast does not expire and is announced immediately.** The other
 * two report something that went as intended, so they can be missed without
 * cost and live 3.6s in a `polite` region that waits its turn. An error is the
 * only thing a toast says that the operator has to act on -- and a run whose
 * upload failed leaves nothing else on screen naming the reason. Letting that
 * sentence disappear after 3.6s, behind whatever a screen reader happened to
 * be reading, would make the failure quieter than the success. So errors sit
 * in an `assertive` region and stay until dismissed.
 *
 * Every toast carries a close button for the same reason: 3.6s is short for a
 * long sentence, and a live region a user cannot dismiss re-announces itself
 * on some readers.
 */

/** How long a toast stays up before it dismisses itself. */
const TOAST_LIFE_MS = 3600

export type ToastTone = 'success' | 'warning' | 'error'

interface Toast {
  id: number
  tone: ToastTone
  message: string
}

interface ToastApi {
  /** Show a toast. Returns nothing -- toasts are fire-and-forget. */
  push: (message: string, tone?: ToastTone) => void
}

const ToastContext = createContext<ToastApi | undefined>(undefined)

const GLYPH: Record<ToastTone, { char: string; className: string }> = {
  success: { char: '✓', className: 'text-green-600' },
  warning: { char: '●', className: 'text-amber-600' },
  error: { char: '●', className: 'text-red-600' },
}

export interface ToastProviderProps {
  children: ReactNode
}

export function ToastProvider({ children }: ToastProviderProps) {
  const [toasts, setToasts] = useState<Toast[]>([])

  const push = useCallback((message: string, tone: ToastTone = 'success') => {
    setToasts((current) => [
      ...current,
      // Not Date.now(): two toasts pushed in the same tick would collide on
      // the React key. A monotonic counter derived from the list cannot.
      { id: (current.at(-1)?.id ?? 0) + 1, tone, message },
    ])
  }, [])

  const dismiss = useCallback((id: number) => {
    setToasts((current) => current.filter((toast) => toast.id !== id))
  }, [])

  const api = useMemo<ToastApi>(() => ({ push }), [push])

  // Two regions, because a region's `aria-live` is fixed at the point the
  // browser starts observing it -- flipping the attribute on one shared region
  // per toast is unreliable across readers. Both are rendered at all times so
  // neither is a newly-inserted live region, which some readers skip.
  return (
    <ToastContext.Provider value={api}>
      {children}
      <div className="pointer-events-none fixed right-5 bottom-5 z-50 flex flex-col gap-2">
        <ToastStack
          toasts={toasts.filter((toast) => toast.tone !== 'error')}
          onDismiss={dismiss}
          live="polite"
          label="Notifications"
          expires
        />
        <ToastStack
          toasts={toasts.filter((toast) => toast.tone === 'error')}
          onDismiss={dismiss}
          live="assertive"
          label="Errors"
          expires={false}
        />
      </div>
    </ToastContext.Provider>
  )
}

function ToastStack({
  toasts,
  onDismiss,
  live,
  label,
  expires,
}: {
  toasts: readonly Toast[]
  onDismiss: (id: number) => void
  live: 'polite' | 'assertive'
  label: string
  expires: boolean
}) {
  return (
    <div role="region" aria-label={label} aria-live={live} className="flex flex-col gap-2">
      {toasts.map((toast) => (
        <ToastItem key={toast.id} toast={toast} onDismiss={onDismiss} expires={expires} />
      ))}
    </div>
  )
}

function ToastItem({
  toast,
  onDismiss,
  expires,
}: {
  toast: Toast
  onDismiss: (id: number) => void
  expires: boolean
}) {
  useEffect(() => {
    if (!expires) return
    const timer = window.setTimeout(() => onDismiss(toast.id), TOAST_LIFE_MS)
    return () => window.clearTimeout(timer)
  }, [toast.id, onDismiss, expires])

  const glyph = GLYPH[toast.tone]

  return (
    <div
      className={cn(
        'pointer-events-auto flex max-w-md items-start gap-2.5 rounded-xl',
        'bg-ink px-3.5 py-2.5 text-xs font-bold text-inverse shadow-xl',
        'animate-rise leading-relaxed text-pretty',
      )}
    >
      <span className={cn('shrink-0 font-bold', glyph.className)} aria-hidden="true">
        {glyph.char}
      </span>
      <span className="min-w-0 flex-1">{toast.message}</span>
      <button
        type="button"
        onClick={() => onDismiss(toast.id)}
        aria-label="Dismiss notification"
        className={cn(
          'shrink-0 cursor-pointer rounded-full border-0 bg-transparent px-1',
          'text-sm font-bold text-inverse/60 hover:text-inverse',
        )}
      >
        <span aria-hidden="true">×</span>
      </button>
    </div>
  )
}

// The provider and its hook are one module by design -- the context object is
// private to this file, so a separate `useToast.ts` would have to export it and
// make the context reachable without the provider. Fast refresh loses this
// file's state on edit; a toast's state is a 3.6s timer, which is not state
// worth restructuring a context around.
// eslint-disable-next-line react-refresh/only-export-components
export function useToast(): ToastApi {
  const api = useContext(ToastContext)
  if (!api) throw new Error('useToast must be used inside <ToastProvider>')
  return api
}
import type { CSSProperties } from 'react'

import { describeProblem, type Problem } from '@/api/problem'
import { cn } from '@/lib/cn'

import { Button } from './Button'

/**
 * Loading and error surfaces.
 *
 * Every list and detail view in this app needs both, so they live together here
 * rather than being re-derived per page. Neither knows a status code or a domain
 * rule: `ErrorState` takes a `Problem` and asks `describeProblem` what it means,
 * which is where the knowledge of this API belongs. (An `EmptyState` used to live
 * beside them and nothing rendered it -- the guestbook says "nothing here" in its
 * own words, `entryListCopy.ts` -- so it went, as `conventions.md` § Frontend asks
 * of a primitive with no caller.)
 */

export interface SkeletonProps {
  className?: string
  style?: CSSProperties
}

/** A static grey block. Skeletons in this system do NOT shimmer. */
export function Skeleton({ className, style }: SkeletonProps) {
  return (
    <div
      className={cn('rounded-md bg-surface-medium', className)}
      style={style}
      aria-hidden="true"
    />
  )
}

export interface ErrorStateProps {
  problem: Problem
  onRetry?: () => void
  className?: string
}

/** The error surface for a failed query or mutation. */
export function ErrorState({ problem, onRetry, className }: ErrorStateProps) {
  const { title, detail, fields, retryable } = describeProblem(problem)

  return (
    <div
      role="alert"
      className={cn(
        'rounded-card border border-hairline bg-card px-6 py-8 text-center',
        className,
      )}
    >
      <p className="m-0 text-base font-bold">{title}</p>
      <p className="mx-auto mt-2 mb-0 max-w-2xl text-sm text-muted leading-relaxed text-pretty">{detail}</p>
      {fields.length > 0 && (
        <ul className="mx-auto mt-3 mb-0 max-w-2xl list-none p-0 text-left text-xs">
          {fields.map(([field, messages]) => (
            <li key={field} className="flex gap-2 border-t border-hairline py-1.5">
              <span className="shrink-0 font-bold text-danger">●</span>
              <span className="min-w-0 flex-1">
                <b>{field === '_' ? 'Request' : field}</b> — {messages.join('; ')}
              </span>
            </li>
          ))}
        </ul>
      )}
      {onRetry !== undefined && retryable && (
        <div className="mt-3.5 flex justify-center">
          <Button variant="outlined" onClick={onRetry}>
            Try again
          </Button>
        </div>
      )}
    </div>
  )
}
import { useCallback, useEffect, useId, useLayoutEffect, useRef } from 'react'
import { createPortal } from 'react-dom'
import type { ReactNode, RefObject } from 'react'

import { cn } from '@/lib/cn'

/**
 * A modal dialog: portal, backdrop, focus trap, inert background, focus restore.
 *
 * Written from scratch rather than pulled in: a dependency-free dialog is
 * ~80 lines of focus handling, and every headless-dialog package would arrive
 * with its own focus-trap and portal opinions to argue with.
 *
 * Everything here is mechanism. It knows nothing about what is being
 * confirmed -- that lives in the caller (`DeleteEntryDialog`), which is what
 * lets the focus behaviour below be reviewed as one thing instead of read past
 * on the way to what it is confirming.
 *
 * **Not `<dialog>` (decision of 2026-09-16, `cr: historical`).** `showModal()`
 * would give the backdrop, the inertness, the entering focus and the Escape
 * handling for free. Three things argue against it, and none of them is the
 * reason this comment used to give -- "this app's `position: absolute`
 * overlays", of which there is not one in the tree:
 *
 * 1. `showModal()` puts the element in the browser's **top layer**, which paints
 *    over every z-index there is. `Toast.tsx` renders its host as an ordinary
 *    `fixed z-50` node that is always mounted, and a failed delete is announced
 *    exactly there -- so `::backdrop` would cover the one region that has
 *    something to say while this dialog is open.
 * 2. `spec/design/ui/guestbook.md` § The delete dialog requires a dialog that is
 *    **not dismissable** while the request is in flight. A `<dialog>` closes on
 *    Escape natively, so keeping that promise means intercepting `cancel` --
 *    which is the same amount of code as owning the key.
 * 3. Both `aria-live` regions are deliberately mounted at all times
 *    (`Toast.tsx`), and moving the dialog to the top layer changes what a reader
 *    observes about a region it is already watching.
 *
 * The parts `<dialog>` would have given are implemented below, and the reason
 * is recorded here rather than left to be rediscovered: an argument written
 * down wrongly is worse than one not written down, because the next reader
 * checks it, finds it false, and throws out the decision with it.
 */

/** Everything Tab should be able to reach inside the dialog. */
const FOCUSABLE =
  'button:not([disabled]), input:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])'

/**
 * The element chain from a node up to `<body>`, closest first.
 *
 * Recorded while the trigger is still in the document, because it is needed
 * after the trigger has left it: a confirmed delete removes the card, and with
 * it the button that opened this dialog.
 */
function lineageOf(element: Element): HTMLElement[] {
  const chain: HTMLElement[] = []
  let node = element.parentElement
  while (node !== null && node !== document.body) {
    chain.push(node)
    node = node.parentElement
  }
  return chain
}

/**
 * Focus `element`, and say whether it actually took it.
 *
 * The whole point. `element.focus()` on a *disabled* button is silently ignored,
 * and so is one on a hidden, `display: none` or detached node -- so asking the
 * document afterwards is the only way to distinguish "focused" from "asked". A
 * null check cannot: a disabled button is a perfectly live `HTMLButtonElement`.
 */
function focusTook(element: HTMLElement | null | undefined): boolean {
  if (element === null || element === undefined) return false
  element.focus()
  return document.activeElement === element
}

