    // the operator moved to inside the dialog.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    // On the document, not on the dialog: clicking a non-focusable part of the
    // dialog moves focus to <body> in some browsers, and Escape has to keep
    // working after that.
    function handleEscape(event: KeyboardEvent) {
      if (event.key === 'Escape') dismiss()
    }
    document.addEventListener('keydown', handleEscape)
    return () => document.removeEventListener('keydown', handleEscape)
  }, [dismiss])

  useEffect(() => {
    /**
     * Keep Tab inside the dialog.
     *
     * `aria-modal` tells assistive technology the rest of the page is inert, and
     * the effect above makes that true for a reader and a mouse -- but a sighted
     * keyboard user still needs the cycle closed, and `inert` is not universally
     * honoured by every environment this runs in (jsdom implements the attribute
     * and none of its behaviour).
     *
     * **On the document, exactly as Escape is, and for the same reason.** This
     * handler used to sit on the overlay's `onKeyDown`. React events propagate up
     * the React tree, and the dialog is rendered as a *sibling* of the page
     * content (`GuestbookPage`), so a keydown from a control behind the modal
     * bubbled through that control's own ancestors and never reached the overlay
     * at all: the handler simply did not run, and the branch below that recovers
     * focus from outside the container was dead code for as long as it existed.
     */
    function handleTab(event: KeyboardEvent) {
      if (event.key !== 'Tab') return
      const container = dialogRef.current
      if (container === null) return

      const nodes = Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE))
      const first = nodes[0]
      const last = nodes.at(-1)
      if (first === undefined || last === undefined) return

      const active = document.activeElement
      const outside = !container.contains(active)
      if (event.shiftKey && (active === first || outside)) {
        event.preventDefault()
        last.focus()
      } else if (!event.shiftKey && (active === last || outside)) {
        event.preventDefault()
        first.focus()
      }
    }

    document.addEventListener('keydown', handleTab)
    return () => document.removeEventListener('keydown', handleTab)
import { useRef } from 'react'

import { Button } from '@/components/ui/Button'
import { Modal } from '@/components/ui/Modal'
import type { GuestbookEntry } from '@/contexts/guestbook/lib/guestbookEntry'

/**
 * The confirmation before an entry is destroyed.
 *
 * **The mock-up deletes on the first click and this does not**, deliberately.
 * Deleting is irreversible (`BR-03`), anybody may delete anybody's entry, and
 * the button that starts it sits a few pixels from "Edit". A mock-up is a
 * drawing of a layout; it is not a decision to remove the only warning a person
 * gets.
 *
 * The dialog quotes the entry back rather than asking "are you sure?" about an
 * unnamed thing: the cards differ only by their text, so a confirmation that
 * does not name what it will destroy cannot be answered correctly.
 *
 * Focus lands on Cancel, not on the destructive action -- an Enter pressed out
 * of habit should not delete anything.
 */
export interface DeleteEntryDialogProps {
  entry: GuestbookEntry
  onConfirm: () => void
  onCancel: () => void
  isPending?: boolean
}

export function DeleteEntryDialog({
  entry,
  onConfirm,
  onCancel,
  isPending = false,
}: DeleteEntryDialogProps) {
  const cancelRef = useRef<HTMLButtonElement>(null)

  return (
    <Modal
      title="Delete this entry?"
      // Undismissable once the request is in flight: there is nothing left to
      // cancel, and a backdrop press would only hide what is still happening.
      onDismiss={isPending ? undefined : onCancel}
      initialFocusRef={cancelRef}
      footer={
        <>
          <span className="text-xs text-muted">This cannot be undone.</span>
          <div className="ml-auto flex gap-2">
            <Button ref={cancelRef} variant="quiet" onClick={onCancel} disabled={isPending}>
              Cancel
            </Button>
            <Button variant="primary" onClick={onConfirm} disabled={isPending}>
              {isPending ? 'Deleting…' : 'Delete entry'}
            </Button>
          </div>
        </>
      }
    >
      <p className="text-sm">
        <b>{entry.author}</b> wrote:

